  (2025, '2º dia — Modelo D', 47, 'ing', 'Compreensão de textos', 'Compreensão geral de textos', 'E', '2025-d2-d Q47: usos históricos dos túneis de Londres'),
  (2025, '2º dia — Modelo D', 48, 'ing', 'Compreensão de textos', 'Compreensão específica de expressões, frases e palavras', 'A', '2025-d2-d Q48: sentido contextual do adjetivo bold'),
  (2025, '2º dia — Modelo D', 49, 'ing', 'Compreensão de textos', 'Compreensão geral de textos', 'C', '2025-d2-d Q49: síntese dos problemas do ensino digital'),
  (2025, '2º dia — Modelo D', 50, 'ing', 'Estruturas gramaticais', 'Conjunctions', 'E', '2025-d2-d Q50: conjunções para completar lacunas'),
  (2025, '2º dia — Modelo D', 51, 'ing', 'Estruturas gramaticais', 'Pronouns', 'D', '2025-d2-d Q51: referentes de where e their'),
